from telegram import InlineKeyboardButton, InlineKeyboardMarkup

@cutiepii_cmd(command='meme')
async def meme(update: Update, context: CallbackContext):
    message = update.effective_message
    try:
        resp = requests.get("https://meme-api.com/gimme/animemes", timeout=10)
        if resp.status_code != 200:
            await message.reply_text("Error fetching meme from API.")
            return
        data = resp.json()
        title = data.get("title", "")
        url = data.get("url", "")
        post_link = data.get("postLink", "")
        subreddit = data.get("subreddit", "animemes")
        
        caption = f"➛ <b>Title</b>: {title}\n➛ <b>Subreddit</b>: <code>r/{subreddit}</code>"
        reply_markup = InlineKeyboardMarkup(
            [[InlineKeyboardButton(text="Subreddit Postlink 🔗", url=post_link)]]
        )
        
        await message.reply_photo(
            photo=url,
            caption=caption,
            reply_markup=reply_markup,
            parse_mode=ParseMode.HTML
        )
    except Exception as e:
        await message.reply_text(f"An error occurred: {e}")


