@cutiepii_cmd(command='hug')
async def hug(update: Update, context: CallbackContext):
    bot: telegram.Bot = context.bot
    args = context.args
    message = update.effective_message
    chat = update.effective_chat
    
    if chat.type == "private":
        await message.reply_text("This command can only be used in groups.")
        return

    user_a = message.from_user
    user_id = await extract_user(message, args)

    if not user_id:
        await message.reply_text("You need to reply to a user's message or provide a username to send a hug request.")
        return

    if user_id == bot.id:
        await message.reply_text("No thanks, I don't need a hug right now.")
        return

    if user_a.id == user_id:
        await message.reply_text("You cannot send a hug request to yourself.")
        return

    try:
        user_b = await bot.get_chat(user_id)
    except Exception:
        await message.reply_text("Could not find the specified user.")
        return

    from telegram import InlineKeyboardButton, InlineKeyboardMarkup
    inline_keyboard = InlineKeyboardMarkup(
        [
            [InlineKeyboardButton("Accept", callback_data=f"accept_hug:{user_a.id}:{user_b.id}")]
        ]
    )

    await message.reply_text(
        f"🤗 <a href='tg://user?id={user_b.id}'>{html.escape(user_b.first_name)}</a>, <a href='tg://user?id={user_a.id}'>{html.escape(user_a.first_name)}</a> wants to send you a hug! 🤗\n\nWill you accept the hug?",
        reply_markup=inline_keyboard,
        parse_mode=ParseMode.HTML
    )

@cutiepii_callback(pattern=r"^accept_hug:")
async def accept_hug_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    bot = context.bot
    data = query.data.split(":")
    user_a_id = int(data[1])
    user_b_id = int(data[2])

    if query.from_user.id != user_b_id:
        await query.answer("Only the recipient can accept this hug request.", show_alert=True)
        return

    try:
        user_a = await bot.get_chat(user_a_id)
        user_b = await bot.get_chat(user_b_id)
    except Exception:
        await query.answer("An error occurred.", show_alert=True)
        return

    await query.message.delete()

    import requests
    img = None
    try:
        r = requests.get("https://api.waifu.pics/sfw/hug")
        if r.status_code == 200:
            img = r.json().get("url")
    except Exception:
        pass

    if not img:
        try:
            r = requests.get("https://nekos.best/api/v2/hug")
            if r.status_code == 200:
                img = r.json()["results"][0]["url"]
        except Exception:
            pass

    caption = f"💞 <a href='tg://user?id={user_b.id}'>{html.escape(user_b.first_name)}</a> accepted the hug from <a href='tg://user?id={user_a.id}'>{html.escape(user_a.first_name)}</a>! 💞"

    if img:
        await bot.send_animation(
            chat_id=query.message.chat.id,
            animation=img,
            caption=caption,
            parse_mode=ParseMode.HTML
        )
    else:
        await bot.send_message(
            chat_id=query.message.chat.id,
            text=caption,
            parse_mode=ParseMode.HTML
        )
    await query.answer()


@cutiepii_cmd(command='pat')
async def pat(update: Update, context: CallbackContext):
    chat_id = update.effective_chat.id
    msg = str(update.message.text)
    resp = requests.get("https://nekos.best/api/v2/pat")
    data = resp.json()
    img = data["results"][0]["url"]
    animename = data["results"][0]["anime_name"]
    try:
        msg = msg.split(" ", 1)[1]
    except IndexError:
        msg = ""
    msg_id = (
        update.effective_message.reply_to_message.message_id
        if update.effective_message.reply_to_message
        else update.effective_message.message_id
    )
    if "@" in msg and len(msg) > 5:
        await context.bot.send_animation(
            chat_id,
            img,
            caption=f"<b>Pat</b> by <code>{animename}</code> to {msg}",
            reply_to_message_id=msg_id,
            parse_mode=ParseMode.HTML
        )
    else:
        await context.bot.send_animation(
            chat_id,
            img,
            caption=f"<b>Pat</b> by <code>{animename}</code>",
            reply_to_message_id=msg_id,
            parse_mode=ParseMode.HTML
        )

