@cutiepii_cmd(command='kiss')
async def kiss(update: Update, context: CallbackContext):
    bot: telegram.Bot = context.bot
    args = context.args
    message = update.effective_message
    chat = update.effective_chat

    if chat.type == "private":
        await message.reply_text("This command can only be used in groups.")
        return

    user_a = message.from_user
    user_id = await extract_user(message, args)

    if not user_id:
        await message.reply_text("You need to reply to a user's message or provide a username to send a kiss request.")
        return

    if user_id == bot.id:
        await message.reply_text("Fuck off, I don't want a kiss from you.")
        return

    if user_a.id == user_id:
        await message.reply_text("Why are you single? You know, nowadays everyone is committed except you!")
        return

    try:
        user_b = await bot.get_chat(user_id)
    except Exception:
        await message.reply_text("Could not find the specified user.")
        return

    from telegram import InlineKeyboardButton, InlineKeyboardMarkup
    inline_keyboard = InlineKeyboardMarkup(
        [
            [InlineKeyboardButton("Accept", callback_data=f"accept_kiss:{user_a.id}:{user_b.id}")]
        ]
    )

    await message.reply_text(
        f"💞 <a href='tg://user?id={user_b.id}'>{html.escape(user_b.first_name)}</a>, <a href='tg://user?id={user_a.id}'>{html.escape(user_a.first_name)}</a> wants to kiss you! 💞\n\nWill you accept the kiss?",
        reply_markup=inline_keyboard,
        parse_mode=ParseMode.HTML
    )

@cutiepii_callback(pattern=r"^accept_kiss:")
async def accept_kiss_callback(update: Update, context: CallbackContext):
    query = update.callback_query
    bot = context.bot
    data = query.data.split(":")
    user_a_id = int(data[1])
    user_b_id = int(data[2])

    if query.from_user.id != user_b_id:
        await query.answer("Only the recipient can accept this kiss request.", show_alert=True)
        return

    try:
        user_a = await bot.get_chat(user_a_id)
        user_b = await bot.get_chat(user_b_id)
    except Exception:
        await query.answer("An error occurred.", show_alert=True)
        return

    await query.message.delete()

    import requests
    img = None
    try:
        r = requests.get("https://api.waifu.pics/sfw/kiss")
        if r.status_code == 200:
            img = r.json().get("url")
    except Exception:
        pass

    if not img:
        try:
            r = requests.get("https://nekos.best/api/v2/kiss")
            if r.status_code == 200:
                img = r.json()["results"][0]["url"]
        except Exception:
            pass

    caption = f"💓 <a href='tg://user?id={user_b.id}'>{html.escape(user_b.first_name)}</a> accepted the kiss from <a href='tg://user?id={user_a.id}'>{html.escape(user_a.first_name)}</a>! 💓"

    if img:
        await bot.send_animation(
            chat_id=query.message.chat.id,
            animation=img,
            caption=caption,
            parse_mode=ParseMode.HTML
        )
    else:
        await bot.send_message(
            chat_id=query.message.chat.id,
            text=caption,
            parse_mode=ParseMode.HTML
        )
    await query.answer()
        
