@cutiepii_cmd(command='rlg')
async def rlg(update: Update, context: CallbackContext):
    from telegram import InlineKeyboardButton, InlineKeyboardMarkup
    eyes = random.choice(fun_strings.EYES)
    mouth = random.choice(fun_strings.MOUTHS)
    ears = random.choice(fun_strings.EARS)

    if len(eyes) == 2:
        repl = ears[0] + eyes[0] + mouth[0] + eyes[1] + ears[1]
    else:
        repl = ears[0] + eyes[0] + mouth[0] + eyes[0] + ears[1]
    
    buttons = [
        [InlineKeyboardButton("🔄 Generate New", callback_data="fun_rlg_repeat")],
        [InlineKeyboardButton("🎭 More Fun", callback_data="fun_help"),
         InlineKeyboardButton("❌ Close", callback_data="close_msg")]
    ]
    await update.message.reply_text(repl, reply_markup=InlineKeyboardMarkup(buttons))


@cutiepii_cmd(command='decide')
async def decide(update: Update, context: CallbackContext):
    from telegram import InlineKeyboardButton, InlineKeyboardMarkup
    msg = update.effective_message
    chat = update.effective_chat
    res = requests.get("https://yesno.wtf/api")
    
    buttons = [
        [InlineKeyboardButton("🔄 Decide Again", callback_data="fun_decide_repeat")],
        [InlineKeyboardButton("🎲 Other Games", callback_data="fun_games"),
         InlineKeyboardButton("❌ Close", callback_data="close_msg")]
    ]
    
    if res.status_code != 200:
         await msg.reply_text(random.choice(fun.DECIDE), reply_markup=InlineKeyboardMarkup(buttons))
         return
    else:
        res = res.json()
    try:
        await context.bot.send_animation(
            chat.id, animation=res.get("image"), 
            caption=str(res.get("answer")).upper(),
            reply_markup=InlineKeyboardMarkup(buttons)
        )
    except BadRequest:
        return

