@cutiepii_cmd(command='kill')
async def kill(update: Update, context: CallbackContext):
    bot: telegram.Bot = context.bot
    args = context.args
    message = update.effective_message
    chat = update.effective_chat

    if chat.type == "private":
        await message.reply_text("This command can only be used in groups.")
        return

    user_a = message.from_user
    user_id = await extract_user(message, args)

    if not user_id:
        await message.reply_text("You need to reply to a user's message or provide a username to kill them.")
        return

    if user_id == bot.id:
        await message.reply_text("You can't kill a bot! 🛡️")
        return

    if user_a.id == user_id:
        await message.reply_text("You can't kill yourself. That's a bit dramatic.")
        return

    try:
        user_b = await bot.get_chat(user_id)
    except Exception:
        await message.reply_text("Could not find the specified user.")
        return

    import requests
    img = None
    try:
        r = requests.get("https://api.waifu.pics/sfw/kill")
        if r.status_code == 200:
            img = r.json().get("url")
    except Exception:
        pass

    if not img:
        try:
            r = requests.get("https://nekos.best/api/v2/kill")
            if r.status_code == 200:
                img = r.json()["results"][0]["url"]
        except Exception:
            pass

    caption = f"💀 <a href='tg://user?id={user_a.id}'>{html.escape(user_a.first_name)}</a> has killed <a href='tg://user?id={user_b.id}'>{html.escape(user_b.first_name)}</a>! 😱"

    if img:
        await bot.send_animation(
            chat_id=chat.id,
            animation=img,
            caption=caption,
            parse_mode=ParseMode.HTML
        )
    else:
        await bot.send_message(
            chat_id=chat.id,
            text=caption,
            parse_mode=ParseMode.HTML
        )

