# Callback handler for fun module buttons
@cutiepii_callback(pattern=r"^fun_")
async def fun_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    from telegram import InlineKeyboardButton, InlineKeyboardMarkup
    query = update.callback_query
    await query.answer()
    data = query.data
    
    if data == "close_msg":
        await query.message.delete()
        return
    
    if data == "fun_help":
        help_text = """
🎭 <b>Fun Commands Categories</b>

<b>🎮 Animations:</b>
/love - Love animation ❣️
/hack - Hacking animation 👨‍💻
/kill - Kill animation ⚰
/moonanimation - Moon phases 🌚
/earthanimation - Earth rotation 🌍
/clockanimation - Clock animation 🕛
/blockanimation - Color blocks 🟥

<b>🎲 Games:</b>
/decide - Yes/No/Maybe
/toss - Coin toss
/roll - Roll dice
/8ball - Magic 8 ball
/rlg - Random emoticon

<b>💝 Interactive:</b>
/hug, /kiss, /pat, /cuddle
/flirt, /romance, /lewd

<b>✨ Text Fun:</b>
/weebify - Weebify text
/shout - Shout text
/owo - OwOify text

Try any command for more fun!
        """
        buttons = [
            [InlineKeyboardButton("🎮 Animations", callback_data="fun_cat_animations"),
             InlineKeyboardButton("🎲 Games", callback_data="fun_cat_games")],
            [InlineKeyboardButton("💝 Interactive", callback_data="fun_cat_interactive"),
             InlineKeyboardButton("✨ Text", callback_data="fun_cat_text")],
            [InlineKeyboardButton("❌ Close", callback_data="close_msg")]
        ]
        await query.message.edit_text(help_text, parse_mode=ParseMode.HTML, 
                                     reply_markup=InlineKeyboardMarkup(buttons))
        return
    
    if data == "fun_games":
        games_text = """
🎲 <b>Fun Games</b>

/decide - Let me decide for you
/toss - Flip a coin
/roll - Roll a dice (1-6)
/8ball - Ask the magic 8-ball
/rlg - Random emoticon generator
/dart - Throw a dart
/basketball - Shoot hoops

<b>Try any game now!</b>
        """
        buttons = [
            [InlineKeyboardButton("🔄 Decide", callback_data="fun_decide_repeat"),
             InlineKeyboardButton("🎲 Roll", callback_data="fun_roll_repeat")],
            [InlineKeyboardButton("🎭 Back to Fun", callback_data="fun_help"),
             InlineKeyboardButton("❌ Close", callback_data="close_msg")]
        ]
        await query.message.edit_text(games_text, parse_mode=ParseMode.HTML,
                                     reply_markup=InlineKeyboardMarkup(buttons))
        return
    
    # Animation repeats
    if data.startswith("fun_") and data.endswith("_repeat"):
        animation_type = data.replace("fun_", "").replace("_repeat", "")
        
        if animation_type == "love":
            msg_text = '❣️'
            for x in range(min(EDIT_TIMES, 10)):
                await query.message.edit_text(love_siren[x%5])
                await asyncio.sleep(1)
            buttons = [
                [InlineKeyboardButton("🔄 Repeat", callback_data="fun_love_repeat"),
                 InlineKeyboardButton("🎭 More Fun", callback_data="fun_help")],
                [InlineKeyboardButton("❌ Close", callback_data="close_msg")]
            ]
            await query.message.edit_text('True Love💞', reply_markup=InlineKeyboardMarkup(buttons))
        
        elif animation_type == "hack":
            for x in range(min(EDIT_TIMES, 6)):
                await query.message.edit_text(hack_you[x%6])
                await asyncio.sleep(1)
            buttons = [
                [InlineKeyboardButton("🔄 Hack Again", callback_data="fun_hack_repeat"),
                 InlineKeyboardButton("🎭 More Fun", callback_data="fun_help")],
                [InlineKeyboardButton("❌ Close", callback_data="close_msg")]
            ]
            await query.message.edit_text('✅ Successfully hacked!', reply_markup=InlineKeyboardMarkup(buttons))
        
        elif animation_type == "kill":
            msg_text = '🔫'
            for x in range(min(EDIT_TIMES, 12)):
                await query.message.edit_text(kill_you[x%12])
                await asyncio.sleep(1)
            buttons = [
                [InlineKeyboardButton("🔄 Repeat", callback_data="fun_kill_repeat"),
                 InlineKeyboardButton("🎭 More Fun", callback_data="fun_help")],
                [InlineKeyboardButton("❌ Close", callback_data="close_msg")]
            ]
            await query.message.edit_text('⚰', reply_markup=InlineKeyboardMarkup(buttons))
        
        elif animation_type == "decide":
            res_data = None
            try:
                res = requests.get("https://yesno.wtf/api", timeout=5)
                if res.status_code == 200:
                    res_data = res.json()
                    answer = str(res_data.get("answer", "maybe")).upper()
                else:
                    answer = random.choice(["YES", "NO", "MAYBE"])
            except:
                answer = random.choice(["YES", "NO", "MAYBE"])
            
            buttons = [
                [InlineKeyboardButton("🔄 Decide Again", callback_data="fun_decide_repeat")],
                [InlineKeyboardButton("🎲 Other Games", callback_data="fun_games"),
                 InlineKeyboardButton("❌ Close", callback_data="close_msg")]
            ]
            
            if query.message.text:
                await query.message.edit_text(f"<b>{answer}</b>", parse_mode=ParseMode.HTML,
                                            reply_markup=InlineKeyboardMarkup(buttons))
            else:
                if res_data and res_data.get("image"):
                    from telegram import InputMediaAnimation
                    try:
                        await query.message.edit_media(
                            media=InputMediaAnimation(media=res_data.get("image"), caption=f"<b>{answer}</b>", parse_mode=ParseMode.HTML),
                            reply_markup=InlineKeyboardMarkup(buttons)
                        )
                    except Exception:
                        try:
                            await query.message.edit_caption(caption=f"<b>{answer}</b>", parse_mode=ParseMode.HTML,
                                                            reply_markup=InlineKeyboardMarkup(buttons))
                        except Exception:
                            pass
                else:
                    try:
                        await query.message.edit_caption(caption=f"<b>{answer}</b>", parse_mode=ParseMode.HTML,
                                                        reply_markup=InlineKeyboardMarkup(buttons))
                    except Exception:
                        pass
        
        elif animation_type == "rlg":
            eyes = random.choice(fun_strings.EYES)
            mouth = random.choice(fun_strings.MOUTHS)
            ears = random.choice(fun_strings.EARS)
            if len(eyes) == 2:
                repl = ears[0] + eyes[0] + mouth[0] + eyes[1] + ears[1]
            else:
                repl = ears[0] + eyes[0] + mouth[0] + eyes[0] + ears[1]
            
            buttons = [
                [InlineKeyboardButton("🔄 Generate New", callback_data="fun_rlg_repeat")],
                [InlineKeyboardButton("🎭 More Fun", callback_data="fun_help"),
                 InlineKeyboardButton("❌ Close", callback_data="close_msg")]
            ]
            await query.message.edit_text(repl, reply_markup=InlineKeyboardMarkup(buttons))


