@cutiepii_cmd(command=["waifus", "neko", "shinobu", "megumin", "bully", "awoo", "lick", "bonk", "nom", "glomp", "cringe"])
async def waifu_pics_gallery(update: Update, context: CallbackContext):
    message = update.effective_message
    chat = update.effective_chat

    # Get the command name used
    text = message.text
    if not text:
        return

    cmd = text.split()[0].lower().replace('/', '').replace('!', '')
    if '@' in cmd:
        cmd = cmd.split('@')[0]

    category_map = {
        "waifus": "waifu",
        "neko": "neko",
        "shinobu": "shinobu",
        "megumin": "megumin",
        "bully": "bully",
        "awoo": "awoo",
        "lick": "lick",
        "bonk": "bonk",
        "nom": "nom",
        "glomp": "glomp",
        "cringe": "cringe"
    }

    category = category_map.get(cmd, cmd)

    import requests
    img = None

    # 1. Try nekos.best (intercepted by custom_get with multiple fallbacks)
    try:
        r = requests.get(f"https://nekos.best/api/v2/{category}")
        if r.status_code == 200:
            img = r.json().get("results")[0].get("url")
    except Exception as e:
        LOGGER.warning(f"Failed to fetch {category} from nekos.best: {e}")

    # 2. Try waifu.pics directly as fallback
    if not img:
        try:
            r = requests.get(f"https://api.waifu.pics/sfw/{category}")
            if r.status_code == 200:
                img = r.json().get("url")
        except Exception as e:
            LOGGER.error(f"Error fetching {category} from waifu.pics: {e}")

    # 3. Try local offline HMTAI JSON databases as absolute fallback for neko
    if not img and category == "neko":
        try:
            from Cutiepii_Robot.modules.helper_funcs.hmtai import sfwNeko
            img = random.choice(sfwNeko)
        except Exception as e:
            LOGGER.error(f"Failed to fetch local neko fallback: {e}")

    if not img:
        await message.reply_text(f"Sorry, I couldn't fetch an image for '{category}' right now.")
        return

    args = context.args
    target_user_id = await extract_user(message, args)

    user_a = message.from_user
    user_b = None
    if target_user_id and target_user_id != context.bot.id:
        try:
            user_b = await context.bot.get_chat(target_user_id)
        except Exception:
            pass

    if user_b:
        caption = f"<b>{category.capitalize()}</b> to <a href='tg://user?id={user_b.id}'>{html.escape(user_b.first_name)}</a>!"
    else:
        caption = f"<b>{category.capitalize()}</b>!"

    try:
        await context.bot.send_animation(
            chat_id=chat.id,
            animation=img,
            caption=caption,
            reply_to_message_id=message.message_id,
            parse_mode=ParseMode.HTML
        )
    except BadRequest:
        try:
            await context.bot.send_photo(
                chat_id=chat.id,
                photo=img,
                caption=caption,
                reply_to_message_id=message.message_id,
                parse_mode=ParseMode.HTML
            )
        except Exception as e:
            LOGGER.error(f"Failed to send image: {e}")





